"""Nonproduction rational-enclosure feasibility proof; no policy authority."""

from __future__ import annotations

from decimal import Decimal, localcontext
from fractions import Fraction
import json
from math import comb
from pathlib import Path


def rational_text(value: Fraction) -> str:
    return f"{value.numerator}/{value.denominator}"


def exponential_enclosure(value: Fraction, terms: int) -> tuple[Fraction, Fraction]:
    """Bracket exp(-value) from a positive Taylor sum and rational tail bound."""
    if value < 0 or terms < 1 or Fraction(terms + 2) <= value:
        raise ValueError("nonnegative argument and convergent tail required")
    term = total = Fraction(1)
    for index in range(1, terms + 1):
        term *= value / index
        total += term
    next_term = term * value / (terms + 1)
    remainder = next_term / (1 - value / (terms + 2))
    return 1 / (total + remainder), 1 / total


def binomial_tail(count: int, successes: int, probability: Fraction, tail: str) -> Fraction:
    if tail not in {"ge", "le"}:
        raise ValueError("unknown tail")
    indices = range(successes, count + 1) if tail == "ge" else range(successes + 1)
    return sum((Fraction(comb(count, index)) * probability**index * (1 - probability) ** (count - index) for index in indices), Fraction())


def binomial_root_enclosure(count: int, successes: int, alpha: Fraction, tail: str, steps: int) -> tuple[Fraction, Fraction]:
    """Bracket either monotone exact-binomial tail root using rational arithmetic."""
    if not 0 <= successes <= count or not 0 < alpha < 1 or steps < 1:
        raise ValueError("invalid binomial root input")
    if (tail == "ge" and successes == 0) or (tail == "le" and successes == count):
        raise ValueError("degenerate binomial root")
    increasing = tail == "ge"
    lower, upper = Fraction(), Fraction(1)
    for _ in range(steps):
        middle = (lower + upper) / 2
        value = binomial_tail(count, successes, middle, tail)
        if (increasing and value < alpha) or (not increasing and value > alpha):
            lower = middle
        else:
            upper = middle
    lower_value = binomial_tail(count, successes, lower, tail)
    upper_value = binomial_tail(count, successes, upper, tail)
    assert (lower_value <= alpha <= upper_value) if increasing else (lower_value >= alpha >= upper_value)
    return lower, upper


def weighted_hoeffding_enclosure(margin: Fraction, squared_range_weight_sum: Fraction, terms: int) -> tuple[str, Fraction, Fraction, Fraction]:
    """Return exponent and an enclosure for the named Section 5.6 tail."""
    if squared_range_weight_sum < 0:
        raise ValueError("nonnegative weighted squared-range sum required")
    if squared_range_weight_sum == 0:
        # All positive-weight cluster ranges are fixed, so this is an exact branch.
        return "degenerate_fixed_value", Fraction(), *( (Fraction(), Fraction()) if margin > 0 else (Fraction(1), Fraction(1)) )
    if margin <= 0:
        return "exponential", Fraction(), Fraction(1), Fraction(1)
    exponent = 2 * margin * margin / squared_range_weight_sum
    lower, upper = exponential_enclosure(exponent, terms)
    return "exponential", exponent, lower, upper


def as_decimal(value: Fraction) -> Decimal:
    return Decimal(value.numerator) / Decimal(value.denominator)


def main() -> None:
    # All literals below are examples, never approved policy values.
    with localcontext() as context:
        context.prec = 100
        exponent_cases = []
        for value in (Fraction(), Fraction(1, 10), Fraction(2), Fraction(20)):
            lower, upper = exponential_enclosure(value, 100)
            assert as_decimal(lower) <= (-as_decimal(value)).exp() <= as_decimal(upper)
            exponent_cases.append({"exponent": rational_text(value), "terms": 100, "lower": rational_text(lower), "upper": rational_text(upper)})
        roots = []
        for count, successes, tail in ((10, 1, "ge"), (10, 4, "ge"), (10, 4, "le"), (10, 9, "le"), (20, 3, "ge"), (20, 17, "le")):
            alpha = Fraction(1, 20)
            lower, upper = binomial_root_enclosure(count, successes, alpha, tail, 40)
            roots.append({"count": count, "successes": successes, "tail": tail, "alpha": rational_text(alpha), "lower": rational_text(lower), "upper": rational_text(upper)})
        hoeffding = []
        for margin, squared_sum in ((Fraction(1, 10), Fraction(1, 4)), (Fraction(3, 20), Fraction(7, 25)), (Fraction(), Fraction(1, 3)), (Fraction(1, 10), Fraction()), (Fraction(), Fraction())):
            branch, exponent, lower, upper = weighted_hoeffding_enclosure(margin, squared_sum, 100)
            if branch == "exponential":
                assert as_decimal(lower) <= (-as_decimal(exponent)).exp() <= as_decimal(upper)
            hoeffding.append({"branch": branch, "margin": rational_text(margin), "squared_range_weight_sum": rational_text(squared_sum), "exponent": rational_text(exponent), "terms": 100, "lower": rational_text(lower), "upper": rational_text(upper)})
    raw_p_values = {"claim-a": Fraction(1, 8), "claim-b": Fraction(1, 8), "claim-c": Fraction(1, 16)}
    holm_order = sorted(raw_p_values, key=lambda claim: (raw_p_values[claim], claim))
    assert holm_order == ["claim-c", "claim-a", "claim-b"]
    result = {"algorithm": "nonproduction-rational-enclosure-feasibility-v2", "binomial_root_certificates": roots, "exponential_certificates": exponent_cases, "weighted_hoeffding_certificates": hoeffding, "holm_exact_tie_certificate": {"raw_p_values": {claim: rational_text(value) for claim, value in raw_p_values.items()}, "canonical_order": holm_order}, "independent_decimal_reference": "100 decimal digits; diagnostic cross-check only", "policy_or_activation_authority": False}
    Path(__file__).with_name("feasibility-result.json").write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="ascii")
    print(json.dumps({"binomial_root_cases": len(roots), "hoeffding_cases": len(hoeffding), "holm_exact_ties": True, "policy_or_activation_authority": False}, sort_keys=True))


if __name__ == "__main__":
    main()

"""Bounded nonproduction proof for numeric-contract resource and mutation rules."""

from __future__ import annotations

from dataclasses import dataclass
from fractions import Fraction
import hashlib
import json


class ResourceLimit(ValueError):
    pass


@dataclass(frozen=True)
class Budget:
    input_bytes: int
    contributions: int
    digits: int
    operations: int
    bits: int
    certificate_bytes: int


class Meter:
    def __init__(self, budget: Budget) -> None:
        self.budget = budget
        self.operations = 0

    def charge(self, count: int = 1) -> None:
        self.operations += count
        if self.operations > self.budget.operations:
            raise ResourceLimit("resource_limit")

    def rational(self, text: str) -> Fraction:
        if len(text.encode("ascii")) > self.budget.input_bytes or len(text.replace("/", "")) > self.budget.digits:
            raise ResourceLimit("resource_limit")
        self.charge()
        numerator, slash, denominator = text.partition("/")
        if not slash or not numerator or not denominator:
            raise ValueError("malformed_rational")
        value = Fraction(int(numerator), int(denominator))
        if f"{value.numerator}/{value.denominator}" != text:
            raise ValueError("malformed_rational")
        if value.numerator.bit_length() > self.budget.bits or value.denominator.bit_length() > self.budget.bits:
            raise ResourceLimit("resource_limit")
        return value

    def evaluate(self, values: list[str]) -> dict[str, object]:
        try:
            if len(values) > self.budget.contributions:
                raise ResourceLimit("resource_limit")
            total = Fraction()
            for value in values:
                total += self.rational(value)
                self.charge()
            certificate = json.dumps({"total": f"{total.numerator}/{total.denominator}"}, sort_keys=True).encode("ascii")
            if len(certificate) > self.budget.certificate_bytes:
                raise ResourceLimit("resource_limit")
            return {"outcome": "passes", "certificate": certificate.decode("ascii")}
        except ResourceLimit:
            return {"outcome": "inconclusive", "failure_code": "resource_limit", "certificate": None}


def require(condition: bool, message: str) -> None:
    if not condition:
        raise ValueError(message)


def digest(value: object) -> str:
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":")).encode("ascii")).hexdigest()


def proof_mutations() -> None:
    binding = {"gate_locator": ["cap", "cell", "metric"], "threshold": "1/2"}
    binding_digest = digest(binding)
    proof = {"kind": "exact_binomial", "binding_digest": binding_digest, "reported": "1/4"}
    bundle = {"binding": binding, "binding_digest": binding_digest, "proof": proof, "proof_digest": digest(proof)}
    require(digest(bundle["binding"]) == bundle["binding_digest"], "binding baseline")
    for mutation in (
        {**proof, "binding_digest": "0" * 64},
        {**proof, "reported": "1/3"},
        {**bundle, "unexpected": True},
    ):
        if "unexpected" in mutation:
            require(set(mutation) != {"binding", "binding_digest", "proof", "proof_digest"}, "schema mutation")
        else:
            require(mutation["binding_digest"] != binding_digest or digest(mutation) != bundle["proof_digest"], "proof mutation")


def main() -> None:
    # Every case proves exact limit succeeds and boundary-plus-one returns no certificate.
    dimensions = {
        "input_bytes": (Budget(3, 1, 2, 2, 2, 32), ["1/2"], Budget(2, 1, 2, 2, 2, 32)),
        "contributions": (Budget(3, 1, 2, 3, 2, 32), ["1/2"], Budget(3, 0, 2, 3, 2, 32)),
        "digits": (Budget(3, 1, 2, 2, 2, 32), ["1/2"], Budget(3, 1, 1, 2, 2, 32)),
        "operations": (Budget(3, 1, 2, 2, 2, 32), ["1/2"], Budget(3, 1, 2, 1, 2, 32)),
        "bits": (Budget(3, 1, 2, 2, 2, 32), ["1/2"], Budget(3, 1, 2, 2, 1, 32)),
        "certificate_bytes": (Budget(3, 1, 2, 2, 2, 16), ["1/2"], Budget(3, 1, 2, 2, 2, 15)),
    }
    for name, (at_limit, values, over_limit) in dimensions.items():
        require(Meter(at_limit).evaluate(values)["outcome"] == "passes", f"{name} limit failed")
        rejected = Meter(over_limit).evaluate(values)
        require(rejected == {"outcome": "inconclusive", "failure_code": "resource_limit", "certificate": None}, f"{name} overflow accepted")
    proof_mutations()
    print(json.dumps({"boundary_dimensions": sorted(dimensions), "mutation_checks": True, "policy_or_activation_authority": False}, sort_keys=True))


if __name__ == "__main__":
    main()

"""Independent nonproduction verifier for the generated rational certificates."""

from fractions import Fraction
import json
from math import comb
from pathlib import Path


def require(condition: bool, message: str) -> None:
    if not condition:
        raise ValueError(message)


def parse(text: str) -> Fraction:
    if not isinstance(text, str):
        raise ValueError("rational must be text")
    numerator, separator, denominator = text.partition("/")
    if not separator or not numerator or not denominator:
        raise ValueError("rational must have canonical numerator/denominator form")
    value = Fraction(int(numerator), int(denominator))
    if value.denominator <= 0 or f"{value.numerator}/{value.denominator}" != text:
        raise ValueError("rational is not canonical")
    return value


def binomial_tail(count: int, successes: int, probability: Fraction, tail: str) -> Fraction:
    if tail not in {"ge", "le"}:
        raise ValueError("unknown binomial tail")
    indices = range(successes, count + 1) if tail == "ge" else range(successes + 1)
    return sum((Fraction(comb(count, index)) * probability**index * (1 - probability) ** (count - index) for index in indices), Fraction())


def independently_enclose_exponential(exponent: Fraction, terms: int) -> tuple[Fraction, Fraction]:
    if exponent < 0 or not isinstance(terms, int) or terms < 1 or Fraction(terms + 2) <= exponent:
        raise ValueError("invalid exponential certificate")
    if exponent == 0:
        return Fraction(1), Fraction(1)
    term = partial_sum = Fraction(1)
    for index in range(1, terms + 1):
        term = term * exponent / index
        partial_sum += term
    omitted_first_term = term * exponent / (terms + 1)
    upper_sum = partial_sum + omitted_first_term / (1 - exponent / (terms + 2))
    return Fraction(1, 1) / upper_sum, Fraction(1, 1) / partial_sum


def validate_holm(raw: dict[str, Fraction], order: list[str]) -> None:
    require(bool(raw), "empty Holm family")
    require(len(order) == len(raw) and set(order) == set(raw), "invalid Holm family")
    require(order == sorted(raw, key=lambda claim: (raw[claim], claim)), "invalid Holm order")


def validate_alpha(alpha: Fraction) -> None:
    require(0 < alpha < 1, "alpha must be interior")


def validate_branch(branch: str) -> None:
    require(branch in {"exponential", "degenerate_fixed_value"}, "unknown Hoeffding branch")


def validate_contributions(contributions: list[object]) -> None:
    require(bool(contributions), "empty contribution evidence")


def mutation_proof() -> None:
    for bad in ("+1/2", "01/2", "2/4", "-0/1", "1/0"):
        try:
            parse(bad)
        except (ValueError, ZeroDivisionError):
            pass
        else:
            raise ValueError("noncanonical rational accepted")
    for bad_tail in ("unknown", "GE"):
        try:
            binomial_tail(1, 0, Fraction(1, 2), bad_tail)
        except ValueError:
            pass
        else:
            raise ValueError("unknown tail accepted")
    for bad_alpha in (Fraction(), Fraction(1)):
        try:
            validate_alpha(bad_alpha)
        except ValueError:
            pass
        else:
            raise ValueError("boundary alpha accepted")
    try:
        validate_branch("unknown")
    except ValueError:
        pass
    else:
        raise ValueError("unknown branch accepted")
    try:
        validate_contributions([])
    except ValueError:
        pass
    else:
        raise ValueError("empty evidence accepted")
    for bad_raw, bad_order in (({}, []), ({"a": Fraction(1, 2)}, ["b"])):
        try:
            validate_holm(bad_raw, bad_order)
        except ValueError:
            pass
        else:
            raise ValueError("invalid Holm family accepted")


def main() -> None:
    value = json.loads(Path(__file__).with_name("feasibility-result.json").read_text(encoding="ascii"))
    expected_top = {"algorithm", "binomial_root_certificates", "exponential_certificates", "holm_exact_tie_certificate", "independent_decimal_reference", "policy_or_activation_authority", "weighted_hoeffding_certificates"}
    require(set(value) == expected_top, "unknown or missing result field")
    require(value["algorithm"] == "nonproduction-rational-enclosure-feasibility-v2", "unknown algorithm")
    require(value["policy_or_activation_authority"] is False, "wrong authority")
    for certificate in value["binomial_root_certificates"]:
        require(set(certificate) == {"count", "successes", "tail", "alpha", "lower", "upper"}, "invalid binomial certificate fields")
        lower, upper, alpha = (parse(certificate[key]) for key in ("lower", "upper", "alpha"))
        require(certificate["tail"] in {"ge", "le"}, "unknown root tail")
        require(certificate["count"] > 0 and 0 <= certificate["successes"] <= certificate["count"], "invalid root domain")
        validate_alpha(alpha)
        require(lower < upper, "empty root interval")
        lower_tail = binomial_tail(certificate["count"], certificate["successes"], lower, certificate["tail"])
        upper_tail = binomial_tail(certificate["count"], certificate["successes"], upper, certificate["tail"])
        require((lower_tail <= alpha <= upper_tail) if certificate["tail"] == "ge" else (lower_tail >= alpha >= upper_tail), "root inequality failed")
    for certificate in value["weighted_hoeffding_certificates"]:
        require(set(certificate) == {"branch", "exponent", "lower", "margin", "squared_range_weight_sum", "terms", "upper"}, "invalid Hoeffding certificate fields")
        exponent, lower, upper, margin, squared_sum = (parse(certificate[key]) for key in ("exponent", "lower", "upper", "margin", "squared_range_weight_sum"))
        validate_branch(certificate["branch"])
        if certificate["branch"] == "degenerate_fixed_value":
            require(squared_sum == 0 and exponent == 0, "invalid degenerate branch")
            require((lower, upper) == ((Fraction(), Fraction()) if margin > 0 else (Fraction(1), Fraction(1))), "wrong degenerate outcome")
            continue
        require(certificate["branch"] == "exponential", "unknown Hoeffding branch")
        require(squared_sum > 0, "invalid weighted range sum")
        require(exponent == (Fraction() if margin <= 0 else 2 * margin * margin / squared_sum), "wrong exponent")
        require(0 < lower <= upper <= 1, "invalid probability interval")
        require((lower, upper) == independently_enclose_exponential(exponent, certificate["terms"]), "wrong exponential enclosure")
    for certificate in value["exponential_certificates"]:
        require(set(certificate) == {"exponent", "lower", "terms", "upper"}, "invalid exponential certificate fields")
        exponent, lower, upper = (parse(certificate[key]) for key in ("exponent", "lower", "upper"))
        require((lower, upper) == independently_enclose_exponential(exponent, certificate["terms"]), "wrong standalone enclosure")
    tie = value["holm_exact_tie_certificate"]
    require(set(tie) == {"canonical_order", "raw_p_values"}, "invalid tie certificate fields")
    raw = {claim: parse(probability) for claim, probability in tie["raw_p_values"].items()}
    validate_holm(raw, tie["canonical_order"])
    mutation_proof()
    print("independent certificate verification: passed")


if __name__ == "__main__":
    main()
